(async () => {
  const { existsSync } = await import('node:fs');
  const inputPath = process.env.INPUT_PATH;
  const outputPath = process.env.OUTPUT_PATH;
  if (!inputPath) throw new Error('Missing INPUT_PATH');
  if (!outputPath) throw new Error('Missing OUTPUT_PATH');
  if (!existsSync(inputPath)) throw new Error('Input file does not exist: ' + inputPath);
  globalThis.inputPath = inputPath;
  globalThis.outputPath = outputPath;
})();

(async () => {
  const fs = await import('node:fs');
  const fastCsv = await import('fast-csv');
  const { parseFile } = fastCsv;
  const rows = [];
  await new Promise((resolve, reject) => {
    parseFile(globalThis.inputPath, { headers: false })
      .on('error', err => reject(err))
      .on('data', row => rows.push(row))
      .on('end', () => resolve());
  });
  if (rows.length === 0) throw new Error('CSV is empty');
  const header = rows[0];
  const body = rows.slice(1);
  const mdLines = [];
  mdLines.push(`| ${header.join(' | ')} |`);
  mdLines.push(`| ${header.map(() => '---').join(' | ')} |`);
  for (const r of body) {
    mdLines.push(`| ${r.join(' | ')} |`);
  }
  const markdown = mdLines.join('\n');
  await fs.promises.writeFile(globalThis.outputPath, markdown, 'utf8');
  globalThis.markdownPath = globalThis.outputPath;
})();
